// Load Config (Reminders) — minimal config for the reminder run (CP5).
// one-swap-to-real: replace this literal with client.config.json / n8n variable (Phase 4/template).
// SHARED keys with the main workflow's Load Config (business.timezone, bot.killSwitch) MUST match —
// guarded by scripts/check-cancel-validation-parity.py (two-Load-Config shared-key assertion).
// CP4c: bot.whatsappSendDisabled is the send brake (killSwitch-level, fail-safe default true) — true = NO
// live Zernio send, the dry-run branch logs the payload instead. channels.whatsapp carries the send identity.
const config = {
  business: { timezone: "Europe/Vienna" },
  bot: { reminderHoursBefore: 24, killSwitch: false, whatsappSendDisabled: true },
  channels: { whatsapp: { enabled: true, provider: "zernio", accountId: "REPLACE_WITH_ZERNIO_ACCOUNT_ID", reminderTemplate: { name: "appointment_reminder", language: "en_US" } } },
  messageTemplates: { reminder: "Reminder: your {service} is booked for {when}. See you soon!" }
};
return [{ json: { ...$json, config } }];

// Compute Reminder Window — the UTC bounds for "due" reminders (CP5).
// Due = booked, not-yet-reminded appointments starting AFTER now and AT/BEFORE now + reminderHoursBefore.
// All UTC (appointments.start_utc is stored UTC); Luxon handles DST at the boundary.
const cfg = $('Load Config (Reminders)').first().json.config;
const hours = cfg.bot.reminderHoursBefore;
const nowUtc = DateTime.utc();
const cutoffUtc = nowUtc.plus({ hours });
return [{ json: {
  ...$json,
  reminder: {
    nowIso: nowUtc.toISO(),
    cutoffIso: cutoffUtc.toISO(),
    tz: cfg.business.timezone
  }
}}];

// Build Reminder Payload — the deterministic outbound reminder for ONE due appointment (CP5).
// Input: one Airtable appointments row ({ id, fields:{...} }). Output: the Phase-4 send contract
// {channel,to,text} + the CP4c whatsapp template send envelope (send_request) + the recordId to stamp.
// {when} rendered in the shop timezone (DST-correct); NO LLM.
const cfg = $('Load Config (Reminders)').first().json.config;
const win = $('Compute Reminder Window').first().json.reminder;
const tz = win.tz;
const f = $json.fields;
const svc = f.service || 'appointment';
const when = DateTime.fromISO(f.start_utc, { zone: 'utc' }).setZone(tz).toFormat('cccc d LLL HH:mm');
const text = (cfg.messageTemplates.reminder || 'Reminder: your {service} is booked for {when}.')
  .replace('{service}', svc)
  .replace('{when}', when);
const senderKey = f.sender_key || '';
const ci = senderKey.indexOf(':');
const channel = ci > 0 ? senderKey.slice(0, ci) : (f.channel || '');
const to = ci > 0 ? senderKey.slice(ci + 1) : senderKey;
// CP4c: whatsapp template send envelope. The reminder is business-initiated, OUTSIDE the 24h window, so
// WhatsApp requires an approved TEMPLATE (not free text). participantId = recipient phone (the 'to').
// templateParams order MUST match the approved template's variable order (CP4d/prod concern).
const wa = (cfg.channels && cfg.channels.whatsapp) || {};
const tpl = wa.reminderTemplate || {};
const send_request = {
  channel,
  accountId: wa.accountId || '',
  participantId: to,
  templateName: tpl.name || '',
  templateLanguage: tpl.language || '',
  templateParams: [svc, when]
};
return [{ json: {
  recordId: $json.id,
  reminder_payload: { channel, to, text },
  send_request,
  _appt: { sender_key: senderKey, service: svc, start_utc: f.start_utc }
}}];

// Reminder Send (dry-run) — the whatsappSendDisabled brake is ON (fail-safe default): NO real Zernio call.
// It surfaces the EXACT template payload the live path would POST (readable in the execution output), then
// passes the recordId through so Stamp Reminded still runs — at-least-once semantics identical to a live send.
const req = $json.send_request;
return [{ json: { recordId: $json.recordId, _dry_run: true, would_post: { url: 'https://zernio.com/api/v1/inbox/conversations', method: 'POST', body: req } } }];
